/**
 * URL-backed state + event bus tests (coordination/README.md D4).
 *
 * The store is what makes searches and selections shareable, so the URL
 * round-trip (state -> query -> state) and the "hand-written URL cannot break
 * the UI" rule are worth pinning down.
 */
import test from 'node:test';
import assert from 'node:assert/strict';

import { PARAM, STATE_DEFAULTS, createBus, createStore, readStateFromUrl, sanitise, stateToQuery } from '../public/app/store.js';

test('defaults describe the documented Zürich initial view', () => {
  assert.equal(STATE_DEFAULTS.lat, 47.3769);
  assert.equal(STATE_DEFAULTS.lon, 8.5417);
  assert.ok(STATE_DEFAULTS.zoom >= 10 && STATE_DEFAULTS.zoom <= 16);
  assert.equal(STATE_DEFAULTS.selected, '');
});

test('readStateFromUrl reads the short shareable parameters', () => {
  const state = readStateFromUrl(`?${new URLSearchParams({ q: 'rheinau', from: '1790', to: '1880', p: 'e-rara', place: 'Rheinau', lat: '47.64', lon: '8.60', z: '13', sel: 'e-rara:11' })}`);
  assert.equal(state.q, 'rheinau');
  assert.equal(state.from, 1790);
  assert.equal(state.to, 1880);
  assert.equal(state.provider, 'e-rara');
  assert.equal(state.place, 'Rheinau');
  assert.equal(state.lat, 47.64);
  assert.equal(state.lon, 8.6);
  assert.equal(state.zoom, 13);
  assert.equal(state.selected, 'e-rara:11');
});

test('stateToQuery omits defaults and round-trips through readStateFromUrl', () => {
  const query = stateToQuery({ ...STATE_DEFAULTS, q: 'uster', from: 1700, selected: 'e-rara:11' });
  const params = new URLSearchParams(query);
  assert.equal(params.get(PARAM.q), 'uster');
  assert.equal(params.has(PARAM.lat), false, 'default view is not repeated in the URL');
  const back = readStateFromUrl(`?${query}`);
  assert.equal(back.q, 'uster');
  assert.equal(back.from, 1700);
  assert.equal(back.selected, 'e-rara:11');
  assert.equal(back.lat, STATE_DEFAULTS.lat);
});

test('sanitise keeps a hand-written URL from breaking the UI', () => {
  const state = sanitise({ ...STATE_DEFAULTS, from: 1900, to: 1500, lat: 'NaN', lon: 900, zoom: 99, view: 'hologram', sort: 'random', q: 'x'.repeat(500) });
  assert.equal(state.from, 1500, 'from/to are ordered');
  assert.equal(state.to, 1900);
  assert.equal(state.lat, STATE_DEFAULTS.lat);
  assert.ok(state.lon >= -180 && state.lon <= 180);
  assert.equal(state.zoom, 18);
  assert.equal(state.view, STATE_DEFAULTS.view);
  assert.equal(state.sort, STATE_DEFAULTS.sort);
  assert.equal(state.q.length, 200, 'free text is capped');
});

test('createStore updates, notifies subscribers with changed keys and stays silent on no-ops', () => {
  const store = createStore({ initial: { q: '' } });
  const seen = [];
  const off = store.subscribe((state, changed) => seen.push([state.q, changed.join(',')]));

  store.update({ q: 'brack', nonsense: 'ignored' });
  assert.equal(store.getState().q, 'brack');
  assert.equal(store.getState().nonsense, undefined, 'unknown keys are ignored');

  store.update({ q: 'brack' }); // no change -> no notification
  store.update({ from: STATE_DEFAULTS.from - 5 }, { silent: true });

  assert.equal(seen.length, 1);
  assert.deepEqual(seen[0], ['brack', 'q']);

  off();
  store.update({ q: 'other' });
  assert.equal(seen.length, 1, 'unsubscribe stops notifications');
});

test('createStore falls back to in-memory state when history/location are unavailable', () => {
  const store = createStore({ history: null, location: null });
  const state = store.update({ q: 'zürich', zoom: 14 });
  assert.equal(state.q, 'zürich');
  assert.equal(store.getState().zoom, 14);
});

test('the bus keeps one failing listener from taking down the others', () => {
  const bus = createBus();
  const calls = [];
  bus.on('ping', () => {
    throw new Error('boom');
  });
  bus.on('ping', (detail) => calls.push(detail));
  const originalError = console.error;
  console.error = () => {};
  try {
    bus.emit('ping', { ok: true });
  } finally {
    console.error = originalError;
  }
  assert.deepEqual(calls, [{ ok: true }]);
});

/**
 * Worker request-handler tests.
 *
 * The Worker only answers `/api/*`; these tests import the real entry module
 * (so anything that would break `wrangler dev` shows up here) and drive it with
 * stubbed `fetch`, `caches.default` and the `ASSETS` binding. No network.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));

// --- Cloudflare runtime stubs -------------------------------------------------
class MemoryCache {
  constructor() {
    this.store = new Map();
  }
  async match(request) {
    const hit = this.store.get(request.url);
    return hit ? hit.clone() : undefined;
  }
  async put(request, response) {
    this.store.set(request.url, response.clone());
  }
}

const cache = new MemoryCache();
globalThis.caches = { default: cache };

const upstreamCalls = [];
let upstreamResponder = () => new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });

globalThis.fetch = async (input, init) => {
  const url = typeof input === 'string' ? input : input.url;
  upstreamCalls.push({ url, init });
  return upstreamResponder(url, init);
};

const { default: worker } = await import('../src/worker/index.js');

/** Minimal ASSETS binding: serves the real files from public/. */
const env = {
  ASSETS: {
    async fetch(request) {
      const url = new URL(request.url);
      const file = path.join(root, 'public', url.pathname.replace(/^\//, ''));
      try {
        const body = await readFile(file);
        const type = url.pathname.endsWith('.json') ? 'application/json' : 'application/octet-stream';
        return new Response(body, { status: 200, headers: { 'content-type': type } });
      } catch {
        return new Response('not found', { status: 404 });
      }
    },
  },
};

const ctx = { waitUntil() {}, passThroughOnException() {} };
const call = (pathname, init) => worker.fetch(new Request(`https://example.test${pathname}`, init), env, ctx);

test.beforeEach(() => {
  upstreamCalls.length = 0;
});

test('the entry module exports only a default ExportedHandler (workerd requirement)', async () => {
  const module = await import('../src/worker/index.js');
  assert.deepEqual(Object.keys(module), ['default'], 'named exports make workerd refuse to start the Worker');
  assert.equal(typeof module.default.fetch, 'function');
  const source = await readFile(path.join(root, 'src/worker/index.js'), 'utf8');
  assert.ok(!/^export\s*\{[^}]*\}/m.test(source), 'no bare re-export of values');
});

test('GET /api/health reports the allowlisted upstreams', async () => {
  const res = await call('/api/health');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.ok, true);
  assert.ok(body.upstreams.includes('api3.geo.admin.ch'));
  assert.ok(body.upstreams.includes('wmts.geo.admin.ch'));
  assert.ok(!body.upstreams.includes('www.oldmapsonline.org'), 'the aggregator is not a data backend');
  assert.deepEqual(body.endpoints, ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch']);
});

test('GET /api/records serves the committed seed data with a cache header', async () => {
  const res = await call('/api/records');
  assert.equal(res.status, 200);
  assert.match(res.headers.get('cache-control'), /max-age=\d+/);
  const body = await res.json();
  assert.ok(Array.isArray(body.records) && body.records.length > 0);
  assert.ok(body.generatedAt);
});

test('GET /api/layers and /api/sources serve the registry files', async () => {
  const layers = await (await call('/api/layers')).json();
  assert.ok(Array.isArray(layers.overlays) && layers.overlays.length > 0);
  const sources = await (await call('/api/sources')).json();
  assert.ok(Array.isArray(sources.providers) && sources.providers.length > 0);
});

test('GET /api/search/places validates input and normalises swisstopo results', async () => {
  const tooShort = await call('/api/search/places?q=z');
  assert.equal(tooShort.status, 400);
  assert.equal((await tooShort.json()).error, 'query_too_short');
  assert.equal(upstreamCalls.length, 0, 'invalid input never reaches the upstream');

  upstreamResponder = () =>
    new Response(
      JSON.stringify({
        results: [
          {
            attrs: {
              label: '<b>Zürich</b> (ZH)',
              lat: 47.3772,
              lon: 8.5273,
              origin: 'gg25',
              geom_st_box2d: 'BOX(8.44688 47.32275,8.62595 47.43414)',
            },
          },
        ],
      }),
      { status: 200, headers: { 'content-type': 'application/json' } },
    );

  const res = await call('/api/search/places?q=Z%C3%BCrich&limit=3');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.results.length, 1);
  assert.equal(body.results[0].label, 'Zürich (ZH)', 'HTML from the upstream label is stripped');
  assert.deepEqual(body.results[0].bbox, { west: 8.44688, south: 47.32275, east: 8.62595, north: 47.43414 });
  assert.equal(body.attribution, '© swisstopo');

  const upstreamUrl = new URL(upstreamCalls.at(-1).url);
  assert.equal(upstreamUrl.hostname, 'api3.geo.admin.ch');
  assert.equal(upstreamUrl.searchParams.get('type'), 'locations');
  assert.equal(upstreamUrl.searchParams.get('sr'), '4326');
  assert.match(upstreamCalls.at(-1).init.headers['user-agent'], /zurich-maps/, 'polite, identifiable User-Agent');
});

test('GET /api/fetch refuses everything outside the host allowlist', async () => {
  const cases = [
    'https://evil.example/manifest.json',
    'http://www.e-rara.ch/i3f/v20/1/manifest',
    'https://www.e-rara.ch.evil.example/i3f/v20/1/manifest',
    'https://www.e-rara.ch/zuz/content/titleinfo/22142031',
    'https://wmts.geo.admin.ch/foo/bar.png',
    'https://api3.geo.admin.ch/rest/services/api/MapServer',
  ];
  for (const target of cases) {
    const res = await call(`/api/fetch?url=${encodeURIComponent(target)}`);
    assert.equal(res.status, 403, `${target} must be refused`);
  }
  assert.equal(upstreamCalls.length, 0, 'refused targets are never fetched');

  const missing = await call('/api/fetch');
  assert.equal(missing.status, 400);
  const invalid = await call('/api/fetch?url=not-a-url');
  assert.equal(invalid.status, 400);
});

test('GET /api/fetch proxies allowlisted IIIF requests with CORS + cache headers', async () => {
  upstreamResponder = () =>
    new Response('{"@context":"http://iiif.io/api/presentation/2/context.json"}', {
      status: 200,
      headers: { 'content-type': 'application/ld+json' },
    });
  const target = 'https://www.e-rara.ch/i3f/v20/22142031/manifest';
  const res = await call(`/api/fetch?url=${encodeURIComponent(target)}&accept=application/json`);
  assert.equal(res.status, 200);
  assert.equal(res.headers.get('access-control-allow-origin'), '*');
  assert.equal(res.headers.get('x-proxied-from'), 'www.e-rara.ch');
  assert.match(res.headers.get('cache-control'), /max-age=\d+/);
  assert.match(upstreamCalls.at(-1).init.headers.accept, /application\/json/);

  const cached = await call(`/api/fetch?url=${encodeURIComponent(target)}`);
  assert.equal(cached.status, 200);
  assert.equal(upstreamCalls.length, 1, 'second identical request is served from the edge cache');
});

test('upstream failures surface as 502 instead of crashing the Worker', async () => {
  upstreamResponder = () => {
    throw new Error('network down');
  };
  const res = await call('/api/fetch?url=' + encodeURIComponent('https://www.e-rara.ch/i3f/v20/1/manifest'));
  assert.equal(res.status, 502);
  assert.equal((await res.json()).error, 'upstream_unreachable');
});

test('non-GET methods and unknown API paths return JSON errors', async () => {
  const post = await call('/api/records', { method: 'POST' });
  assert.equal(post.status, 405);
  assert.equal(post.headers.get('allow'), 'GET, HEAD');
  const unknown = await call('/api/nope');
  assert.equal(unknown.status, 404);
  assert.equal((await unknown.json()).error, 'not_found');
});

test('non-API requests fall through to the static assets binding', async () => {
  const res = await call('/app/main.js');
  assert.equal(res.status, 200);
});

content.thinking:
The lon normalisation formula `((((lon + 180) % 360) + 360) % 360) - 180` introduces float error: 8.6 → 8.600000000000023. Actually that's a *real* minor bug: for a plain lon of 8.6 the value passes through the modulo arithmetic unnecessarily and gets floating-point drift, which then serialises as "8.6000" (fine) but the state value is imprecise and comparisons (`value === defaults[key]`) can misbehave. Better fix in store.js: only normalise when out of range, and round to a sane precision.

Since store.js is maps-1's file but this is a small, well-understood bug fix, I'll fix it and note it in coordination. Let me implement:

```js
out.lon = normaliseLon(Number(out.lon) || STATE_DEFAULTS.lon);
```
with
```js
function normaliseLon(lon) {
  if (!Number.isFinite(lon)) return STATE_DEFAULTS.lon;
  if (lon >= -180 && lon <= 180) return lon; // in range: keep the exact value
  const wrapped = ((((lon + 180) % 360) + 360) % 360) - 180;
  return Math.round(wrapped * 1e6) / 1e6;
}
```
Also lat could get rounding? lat is only clamped, fine.

Similarly `stateToQuery` uses toFixed(4) for lat/lon which is a deliberate rounding — fine.

Let me make that edit.

